/**
 * PSRD Product Manager - Cloudflare Worker (single file, paste-and-deploy)
 * ------------------------------------------------------------------------
 * Serves the product manager app at "/" and securely proxies the GHL API.
 * The GHL token NEVER reaches the browser.
 *
 * SETUP (one time, ~2 minutes):
 *   1. Cloudflare dashboard -> Workers & Pages -> Create -> Worker -> paste this file -> Deploy
 *   2. Worker -> Settings -> Variables and Secrets -> add TWO secrets:
 *        GHL_TOKEN = pit-...   (your GHL Private Integration Token)
 *        APP_PASS  = ........  (the password you want to type at the app gate)
 *   3. Open the worker URL. Type APP_PASS. Done.
 *
 * Routes:
 *   GET  /                      -> the app
 *   POST /api/login             -> verifies gate password against APP_PASS
 *   GET  /api/fetch?url=...     -> server-side image fetch (agent-generated URLs, no CORS)
 *   *    /api/ghl/<path>        -> proxied to https://services.leadconnectorhq.com/<path>
 *                                  with Authorization + Version headers injected
 * All /api/* routes (except /api/login) require header X-PSRD-Key = APP_PASS.
 */

const GHL_ORIGIN = 'https://services.leadconnectorhq.com';
const GHL_VERSION = '2021-07-28';

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const path = url.pathname;

    // ---- App shell ----
    if (request.method === 'GET' && (path === '/' || path === '/index.html')) {
      return new Response(APP_HTML, {
        headers: { 'content-type': 'text/html;charset=utf-8', 'cache-control': 'no-store' }
      });
    }

    if (!path.startsWith('/api/')) return new Response('Not found', { status: 404 });

    // ---- Login: verify gate password against the APP_PASS secret ----
    if (path === '/api/login' && request.method === 'POST') {
      let body = {};
      try { body = await request.json(); } catch (e) {}
      if (!env.APP_PASS) return json({ ok: false, error: 'APP_PASS secret is not set on the Worker. Add it under Settings \u2192 Variables and Secrets, then Deploy.' }, 500);
      if (!env.GHL_TOKEN) return json({ ok: false, error: 'GHL_TOKEN secret is not set on the Worker. Add it under Settings \u2192 Variables and Secrets, then Deploy.' }, 500);
      if (body.password === env.APP_PASS) return json({ ok: true });
      return json({ ok: false, error: 'Incorrect password (must exactly match the APP_PASS secret).' }, 401);
    }

    // ---- Auth for every other /api route ----
    const key = request.headers.get('X-PSRD-Key') || '';
    if (!env.APP_PASS || key !== env.APP_PASS) return json({ error: 'unauthorized' }, 401);
    if (!env.GHL_TOKEN) return json({ error: 'GHL_TOKEN secret is not set on the Worker' }, 500);

    // ---- Server-side image fetch (for agent-generated image URLs) ----
    if (path === '/api/fetch' && request.method === 'GET') {
      const target = url.searchParams.get('url') || '';
      if (!/^https?:\/\//i.test(target)) return json({ error: 'bad url' }, 400);
      try {
        const r = await fetch(target, { redirect: 'follow' });
        return new Response(r.body, {
          status: r.status,
          headers: {
            'content-type': r.headers.get('content-type') || 'application/octet-stream',
            'cache-control': 'no-store'
          }
        });
      } catch (e) {
        return json({ error: 'fetch failed: ' + String(e) }, 502);
      }
    }

    // ---- GHL API proxy ----
    if (path.startsWith('/api/ghl/')) {
      const target = GHL_ORIGIN + path.slice('/api/ghl'.length) + url.search;
      const headers = new Headers();
      headers.set('Authorization', 'Bearer ' + env.GHL_TOKEN);
      headers.set('Version', GHL_VERSION);
      headers.set('Accept', 'application/json');
      const ct = request.headers.get('content-type');
      if (ct) headers.set('content-type', ct); // preserves multipart boundary for media uploads
      const init = { method: request.method, headers, redirect: 'follow' };
      if (request.method !== 'GET' && request.method !== 'HEAD') {
        init.body = await request.arrayBuffer();
      }
      try {
        const r = await fetch(target, init);
        return new Response(r.body, {
          status: r.status,
          headers: {
            'content-type': r.headers.get('content-type') || 'application/json',
            'cache-control': 'no-store'
          }
        });
      } catch (e) {
        return json({ error: 'upstream failure: ' + String(e) }, 502);
      }
    }

    return json({ error: 'not found' }, 404);
  }
};

function json(obj, status = 0) {
  return new Response(JSON.stringify(obj), {
    status: status || 200,
    headers: { 'content-type': 'application/json', 'cache-control': 'no-store' }
  });
}

